(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.02+t*0.32)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*8 + Math.cos((y+w1y)*0.02+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.2)*8 + Math.sin((x+w1x)*0.028-t*0.17)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.055, 2.8, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS += Math.sin(d*f*0.45-t*sp*0.35+3.0)*w*0.5;
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, harm=hS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+Math.cos(sy*0.06+t)*3+t*1.5)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.07-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2 = Math.tanh((harm-inh*0.5+act*0.4-spiral*0.3)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.12;
  const blend = rd1*0.5+rd2*0.2+cell*0.2+micro*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,78,108],[24,128,128],
    [45,165,135],[130,190,110],[200,195,80],
    [220,160,65],[210,110,60],[175,60,60],
    [110,30,55],[50,15,48],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const lum = 0.82+Math.sin(rd1*Math.PI)*0.18;
  const edge = Math.abs(rd1)>0.65?1.12:Math.abs(rd2)>0.5?1.06:1.0;
  const glow = Math.max(0, rd1*rd2)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*100)|0
  ];
}
